2	<html lang="en">
3	<head>
4	<meta charset="UTF-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1.0">
6	<title>CI/CD Pipeline — Reference Template</title>
7	<!--
8	  Reference template for the visual-explainer skill: Mermaid diagrams.
9	  Teal/cyan palette — distinctly different from terracotta (architecture)
10	  and rose (data-table) templates so agents absorb variety.
11	  Key patterns demonstrated:
12	  - Teal/cyan palette (NOT indigo/violet)
13	  - Dot-grid background atmosphere (different from radial gradient)
14	  - Large heading (38px) for typographic contrast
15	  - ESM import of Mermaid + @mermaid-js/layout-elk
16	  - Mermaid theme: 'base' + full themeVariables, fontSize: 16px
17	  - CSS overrides: .nodeLabel 16px, .edgeLabel 13px
18	  - look: 'classic' for clean lines
19	  - layout: 'elk' for better node positioning
20	  - Zoom controls with scroll-to-zoom and drag-to-pan
21	  - Both light and dark themes via prefers-color-scheme
22	  - Staggered fade-in, reduced motion respect
23	-->
24	<link rel="preconnect" href="https://fonts.googleapis.com">
25	<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
26	<link href="https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:wght@400;500;600;700&family=Fragment+Mono:wght@400&display=swap" rel="stylesheet">
27	<style>
28	  /* ============ THEME ============ */
29	  :root {
30	    --font-body: 'Bricolage Grotesque', system-ui, sans-serif;
31	    --font-mono: 'Fragment Mono', 'SF Mono', Consolas, monospace;
32	
33	    --bg: #f0fdfa;
34	    --surface: #ffffff;
35	    --border: rgba(0, 0, 0, 0.07);
36	    --text: #134e4a;
37	    --text-dim: #5f8a85;
38	
39	    --primary: #0d9488;
40	    --primary-dim: rgba(13, 148, 136, 0.08);
41	    --secondary: #0369a1;
42	    --tertiary: #d97706;
43	    --danger: #dc2626;
44	  }
45	
46	  @media (prefers-color-scheme: dark) {
47	    :root {
48	      --bg: #042f2e;
49	      --surface: #0a3d3a;
50	      --border: rgba(255, 255, 255, 0.08);
51	      --text: #ccfbf1;
52	      --text-dim: #5eead4;
53	
54	      --primary: #2dd4bf;
55	      --primary-dim: rgba(45, 212, 191, 0.14);
56	      --secondary: #38bdf8;
57	      --tertiary: #fbbf24;
58	      --danger: #f87171;
59	    }
60	  }
61	
62	  /* ============ RESET + BASE ============ */
63	  * { margin: 0; padding: 0; box-sizing: border-box; }
64	
65	  body {
66	    background-color: var(--bg);
67	    background-image: radial-gradient(circle, var(--border) 1px, transparent 1px);
68	    background-size: 24px 24px;
69	    color: var(--text);
70	    font-family: var(--font-body);
71	    padding: 40px;
72	    min-height: 100vh;
73	  }
74	
75	  /* ============ ANIMATION ============ */
76	  @keyframes fadeUp {
77	    from { opacity: 0; transform: translateY(12px); }
78	    to { opacity: 1; transform: translateY(0); }
79	  }
80	
81	  .animate {
82	    animation: fadeUp 0.4s ease-out both;
83	    animation-delay: calc(var(--i, 0) * 0.06s);
84	  }
85	
86	  @media (prefers-reduced-motion: reduce) {
87	    *, *::before, *::after {
88	      animation-duration: 0.01ms !important;
89	      animation-delay: 0ms !important;
90	      transition-duration: 0.01ms !important;
91	    }
92	  }
93	
94	  /* ============ LAYOUT ============ */
95	  .container {
96	    max-width: 1000px;
97	    margin: 0 auto;
98	  }
99	
100	  h1 {
101	    font-size: 38px;
102	    font-weight: 700;
103	    letter-spacing: -1px;
104	    margin-bottom: 6px;
105	    text-wrap: balance;
106	  }
107	
108	  .subtitle {
109	    color: var(--text-dim);
110	    font-family: var(--font-mono);
111	    font-size: 12px;
112	    margin-bottom: 32px;
113	  }
114	
115	  .description {
116	    font-size: 14px;
117	    line-height: 1.7;
118	    color: var(--text-dim);
119	    margin-bottom: 24px;
120	    max-width: 700px;
121	  }
122	
123	  .description code {
124	    font-family: var(--font-mono);
125	    font-size: 12px;
126	    background: var(--primary-dim);
127	    color: var(--primary);
128	    padding: 1px 5px;
129	    border-radius: 3px;
130	  }
131	
132	  /* ============ MERMAID CONTAINER ============ */
133	  .mermaid-wrap {
134	    position: relative;
135	    background: var(--surface);
136	    border: 1px solid var(--border);
137	    border-radius: 12px;
138	    padding: 32px 24px;
139	    overflow: auto;
140	    margin-bottom: 24px;
141	    display: flex;
142	    justify-content: center;
143	    align-items: center;
144	    min-height: 400px;
145	  }
146	
147	  .zoom-controls {
148	    position: absolute;
149	    top: 8px;
150	    right: 8px;
151	    display: flex;
152	    gap: 2px;
153	    z-index: 10;
154	    background: var(--surface);
155	    border: 1px solid var(--border);
156	    border-radius: 6px;
157	    padding: 2px;
158	  }
159	
160	  .zoom-controls button {
161	    width: 28px;
162	    height: 28px;
163	    border: none;
164	    background: transparent;
165	    color: var(--text-dim);
166	    font-family: var(--font-mono);
167	    font-size: 14px;
168	    cursor: pointer;
169	    border-radius: 4px;
170	    display: flex;
171	    align-items: center;
172	    justify-content: center;
173	    transition: background 0.15s ease, color 0.15s ease;
174	  }
175	
176	  .zoom-controls button:hover {
177	    background: var(--border);
178	    color: var(--text);
179	  }
180	
181	  .mermaid-wrap { cursor: grab; }
182	  .mermaid-wrap.is-panning { cursor: grabbing; user-select: none; }
183	
184	  /* ============ MULTI-DIAGRAM STRUCTURE ============ */
185	  .diagram-shell {
186	    position: relative;
187	  }
188	
189	  .diagram-shell__hint {
190	    font-family: var(--font-mono);
191	    font-size: 11px;
192	    color: var(--text-dim);
193	    margin-bottom: 8px;
194	    opacity: 0.7;
195	  }
196	
197	  .mermaid-viewport {
198	    position: relative;
199	    overflow: hidden;
200	    width: 100%;
201	    height: 100%;
202	    min-height: 300px;
203	  }
204	
205	  .mermaid-canvas {
206	    position: absolute;
207	    top: 0;
208	    left: 0;
209	  }
210	
211	  .zoom-label {
212	    font-family: var(--font-mono);
213	    font-size: 10px;
214	    color: var(--text-dim);
215	    padding: 0 6px;
216	    white-space: nowrap;
217	  }
218	
219	  /* ============ MERMAID SVG OVERRIDES ============ */
220	  .mermaid .nodeLabel {
221	    font-family: var(--font-body) !important;
222	    font-size: 16px !important;
223	  }
224	
225	  .mermaid .edgeLabel {
226	    font-family: var(--font-mono) !important;
227	    font-size: 13px !important;
228	  }
229	
230	  .mermaid .node rect,
231	  .mermaid .node circle,
232	  .mermaid .node polygon {
233	    stroke-width: 1.5px !important;
234	  }
235	
236	  .mermaid .edge-pattern-solid {
237	    stroke-width: 1.5px !important;
238	  }
239	
240	  /* ============ LEGEND ============ */
241	  .legend {
242	    display: flex;
243	    gap: 20px;
244	    flex-wrap: wrap;
245	  }
246	
247	  .legend-item {
248	    display: flex;
249	    align-items: center;
250	    gap: 6px;
251	    font-family: var(--font-mono);
252	    font-size: 11px;
253	    color: var(--text-dim);
254	  }
255	
256	  .legend-swatch {
257	    width: 12px;
258	    height: 12px;
259	    border-radius: 3px;
260	  }
261	
262	  /* ============ CALLOUT ============ */
263	  .callout {
264	    background: var(--surface);
265	    border: 1px solid var(--border);
266	    border-left: 3px solid var(--primary);
267	    border-radius: 0 10px 10px 0;
268	    padding: 16px 20px;
269	    font-size: 13px;
270	    line-height: 1.6;
271	    color: var(--text-dim);
272	    margin-top: 24px;
273	  }
274	
275	  .callout strong { color: var(--text); }
276	
277	  .callout code {
278	    font-family: var(--font-mono);
279	    font-size: 11px;
280	    background: var(--primary-dim);
281	    color: var(--primary);
282	    padding: 1px 5px;
283	    border-radius: 3px;
284	  }
285	
286	  /* ============ RESPONSIVE ============ */
287	  @media (max-width: 768px) {
288	    body { padding: 16px; }
289	    h1 { font-size: 22px; }
290	    .mermaid-wrap { padding: 16px 12px; }
291	  }
292	</style>
293	</head>
294	<body>
295	
296	<div class="container">
297	
298	  <h1 class="animate" style="--i:0">CI/CD Pipeline</h1>
299	  <p class="subtitle animate" style="--i:1">github actions &rarr; staging &rarr; production</p>
300	
301	  <p class="description animate" style="--i:2">
302	    Every push to <code>main</code> triggers the full pipeline. Tests and linting run in parallel,
303	    then the build step produces a Docker image. Staging deploys automatically; production requires
304	    manual approval via a GitHub environment gate.
305	  </p>
306	
307	  <section class="diagram-shell animate" style="--i:3">
308	    <p class="diagram-shell__hint">
309	      Ctrl/Cmd + wheel to zoom. Scroll to pan. Drag to pan when zoomed. Double-click to fit.
310	    </p>
311	    <div class="mermaid-wrap">
312	      <div class="zoom-controls">
313	        <button type="button" data-action="zoom-in" title="Zoom in">+</button>
314	        <button type="button" data-action="zoom-out" title="Zoom out">&minus;</button>
315	        <button type="button" data-action="zoom-fit" title="Smart fit">&#8634;</button>
316	        <button type="button" data-action="zoom-one" title="1:1 zoom">1:1</button>
317	        <button type="button" data-action="zoom-expand" title="Open full size">&#x26F6;</button>
318	        <span class="zoom-label">Loading...</span>
319	      </div>
320	      <div class="mermaid-viewport">
321	        <div class="mermaid mermaid-canvas"></div>
322	      </div>
323	    </div>
324	    <script type="text/plain" class="diagram-source">
325	      graph TD
326	        A[Push to main] --> B{Branch?}
327	        B -->|main| C[Run Tests]
328	        B -->|feature| I[Run Tests]
329	        I --> J[Preview Deploy]
330	        C --> D[Lint + Type Check]
331	        C --> E[Unit Tests]
332	        C --> F[Integration Tests]
333	        D --> G[Build Docker Image]
334	        E --> G
335	        F --> G
336	        G --> H[Deploy to Staging]
337	        H --> K{Smoke Tests Pass?}
338	        K -->|Yes| L[Manual Approval]
339	        K -->|No| M[Alert + Rollback]
340	        L --> N[Deploy to Production]
341	        N --> O[Health Check]
342	        O --> P[Done]
343	    </script>
344	  </section>
345	
346	  <div class="legend animate" style="--i:4">
347	    <div class="legend-item"><div class="legend-swatch" style="background:var(--primary)"></div> Automated step</div>
348	    <div class="legend-item"><div class="legend-swatch" style="background:var(--tertiary)"></div> Decision gate</div>
349	    <div class="legend-item"><div class="legend-swatch" style="background:var(--danger)"></div> Failure path</div>
350	    <div class="legend-item"><div class="legend-swatch" style="background:var(--secondary)"></div> Success</div>
351	  </div>
352	
353	  <div class="callout animate" style="--i:5">
354	    <strong>ELK layout.</strong> The <code>layout: 'elk'</code> engine provides better node positioning
355	    for complex graphs — it requires the separate <code>@mermaid-js/layout-elk</code> package (imported above).
356	    Without it, Mermaid silently falls back to dagre.
357	  </div>
358	
359	</div>
360	
361	<script type="module">
362	  import mermaid from '/app/libs/mermaid.esm.min.mjs';
363	  import elkLayouts from '/app/libs/mermaid-layout-elk.esm.min.mjs';
364	
365	  const config = {
366	    fitPadding: 28,
367	    minHeight: 360,
368	    maxHeightPx: 960,
369	    maxHeightVh: 0.84,
370	    maxInitialZoom: 1.8,
371	    minZoom: 0.08,
372	    maxZoom: 6.5,
373	    zoomStep: 0.14,
374	    readabilityFloor: 0.58
375	  };
376	
377	  const clamp = (n, lo, hi) => Math.max(lo, Math.min(hi, n));
378	
379	  let activeDrag = null;
380	
381	  addEventListener('mousemove', (e) => activeDrag?.onMove(e));
382	  addEventListener('mouseup', () => {
383	    activeDrag?.onEnd();
384	    activeDrag = null;
385	  });
386	
387	  const isDark = matchMedia('(prefers-color-scheme: dark)').matches;
388	
389	  mermaid.registerLayoutLoaders(elkLayouts);
390	  mermaid.initialize({
391	    startOnLoad: false,
392	    theme: 'base',
393	    look: 'classic',
394	    layout: 'elk',
395	    themeVariables: {
396	      fontFamily: "'Bricolage Grotesque', system-ui, sans-serif",
397	      fontSize: '16px',
398	      primaryColor: isDark ? '#115e59' : '#ccfbf1',
399	      primaryBorderColor: isDark ? '#2dd4bf' : '#0d9488',
400	      primaryTextColor: isDark ? '#ccfbf1' : '#134e4a',
401	      secondaryColor: isDark ? '#0c4a6e' : '#e0f2fe',
402	      secondaryBorderColor: isDark ? '#38bdf8' : '#0369a1',
403	      secondaryTextColor: isDark ? '#ccfbf1' : '#134e4a',
404	      tertiaryColor: isDark ? '#2e2618' : '#fffbeb',
405	      tertiaryBorderColor: isDark ? '#fbbf24' : '#d97706',
406	      tertiaryTextColor: isDark ? '#ccfbf1' : '#134e4a',
407	      lineColor: isDark ? '#5eead4' : '#5f8a85',
408	      noteBkgColor: isDark ? '#115e59' : '#fefce8',
409	      noteTextColor: isDark ? '#ccfbf1' : '#134e4a',
410	      noteBorderColor: isDark ? '#fbbf24' : '#d97706',
411	    }
412	  });
413	
414	  function initDiagram(shell) {
415	    const wrap = shell.querySelector('.mermaid-wrap');
416	    const viewport = shell.querySelector('.mermaid-viewport');
417	    const canvas = shell.querySelector('.mermaid-canvas');
418	    const source = shell.querySelector('.diagram-source');
419	    const label = shell.querySelector('.zoom-label');
420	
421	    if (!wrap || !viewport || !canvas || !source || !label) {
422	      console.error('initDiagram: missing required elements in', shell);
423	      return;
424	    }
425	
426	    let zoom = 1;
427	    let fitMode = 'contain';
428	    let panX = 0;
429	    let panY = 0;
430	    let svgW = 0;
431	    let svgH = 0;
432	
433	    let sx = 0;
434	    let sy = 0;
435	    let spx = 0;
436	    let spy = 0;
437	
438	    let touchDist = 0;
439	    let touchCx = 0;
440	    let touchCy = 0;
441	
442	    function constrainPan() {
443	      const vpW = viewport.clientWidth;
444	      const vpH = viewport.clientHeight;
445	      const rW = svgW * zoom;
446	      const rH = svgH * zoom;
447	      const pad = config.fitPadding;
448	
449	      panX = (rW + pad * 2 <= vpW)
450	        ? (vpW - rW) / 2
451	        : clamp(panX, vpW - rW - pad, pad);
452	      panY = (rH + pad * 2 <= vpH)
453	        ? (vpH - rH) / 2
454	        : clamp(panY, vpH - rH - pad, pad);
455	    }
456	
457	    function applyTransform() {
458	      const svg = canvas.querySelector('svg');
459	      if (!svg || !svgW) return;
460	
461	      constrainPan();
462	      svg.style.width = (svgW * zoom) + 'px';
463	      svg.style.height = (svgH * zoom) + 'px';
464	      canvas.style.transform = `translate(${panX}px, ${panY}px)`;
465	      label.textContent = Math.round(zoom * 100) + '% \u2014 ' + fitMode;
466	    }
467	
468	    function canPan() {
469	      const rW = svgW * zoom;
470	      const rH = svgH * zoom;
471	      return rW + config.fitPadding * 2 > viewport.clientWidth
