361	<script type="module">
362	  import mermaid from '/app/libs/mermaid.esm.min.mjs';
363	  import elkLayouts from '/app/libs/mermaid-layout-elk.esm.min.mjs';
364	
365	  const config = {
366	    fitPadding: 28,
367	    minHeight: 360,
368	    maxHeightPx: 960,
369	    maxHeightVh: 0.84,
370	    maxInitialZoom: 1.8,
371	    minZoom: 0.08,
372	    maxZoom: 6.5,
373	    zoomStep: 0.14,
374	    readabilityFloor: 0.58
375	  };
376	
377	  const clamp = (n, lo, hi) => Math.max(lo, Math.min(hi, n));
378	
379	  let activeDrag = null;
380	
381	  addEventListener('mousemove', (e) => activeDrag?.onMove(e));
382	  addEventListener('mouseup', () => {
383	    activeDrag?.onEnd();
384	    activeDrag = null;
385	  });
386	
387	  const isDark = matchMedia('(prefers-color-scheme: dark)').matches;
388	
389	  mermaid.registerLayoutLoaders(elkLayouts);
390	  mermaid.initialize({
391	    startOnLoad: false,
392	    theme: 'base',
393	    look: 'classic',
394	    layout: 'elk',
395	    themeVariables: {
396	      fontFamily: "'Bricolage Grotesque', system-ui, sans-serif",
397	      fontSize: '16px',
398	      primaryColor: isDark ? '#115e59' : '#ccfbf1',
399	      primaryBorderColor: isDark ? '#2dd4bf' : '#0d9488',
400	      primaryTextColor: isDark ? '#ccfbf1' : '#134e4a',
401	      secondaryColor: isDark ? '#0c4a6e' : '#e0f2fe',
402	      secondaryBorderColor: isDark ? '#38bdf8' : '#0369a1',
403	      secondaryTextColor: isDark ? '#ccfbf1' : '#134e4a',
404	      tertiaryColor: isDark ? '#2e2618' : '#fffbeb',
405	      tertiaryBorderColor: isDark ? '#fbbf24' : '#d97706',
406	      tertiaryTextColor: isDark ? '#ccfbf1' : '#134e4a',
407	      lineColor: isDark ? '#5eead4' : '#5f8a85',
408	      noteBkgColor: isDark ? '#115e59' : '#fefce8',
409	      noteTextColor: isDark ? '#ccfbf1' : '#134e4a',
410	      noteBorderColor: isDark ? '#fbbf24' : '#d97706',
411	    }
412	  });
413	
414	  function initDiagram(shell) {
415	    const wrap = shell.querySelector('.mermaid-wrap');
416	    const viewport = shell.querySelector('.mermaid-viewport');
417	    const canvas = shell.querySelector('.mermaid-canvas');
418	    const source = shell.querySelector('.diagram-source');
419	    const label = shell.querySelector('.zoom-label');
420	
421	    if (!wrap || !viewport || !canvas || !source || !label) {
422	      console.error('initDiagram: missing required elements in', shell);
423	      return;
424	    }
425	
426	    let zoom = 1;
427	    let fitMode = 'contain';
428	    let panX = 0;
429	    let panY = 0;
430	    let svgW = 0;
431	    let svgH = 0;
432	
433	    let sx = 0;
434	    let sy = 0;
435	    let spx = 0;
436	    let spy = 0;
437	
438	    let touchDist = 0;
439	    let touchCx = 0;
440	    let touchCy = 0;
441	
442	    function constrainPan() {
443	      const vpW = viewport.clientWidth;
444	      const vpH = viewport.clientHeight;
445	      const rW = svgW * zoom;
446	      const rH = svgH * zoom;
447	      const pad = config.fitPadding;
448	
449	      panX = (rW + pad * 2 <= vpW)
450	        ? (vpW - rW) / 2
451	        : clamp(panX, vpW - rW - pad, pad);
452	      panY = (rH + pad * 2 <= vpH)
453	        ? (vpH - rH) / 2
454	        : clamp(panY, vpH - rH - pad, pad);
455	    }
456	
457	    function applyTransform() {
458	      const svg = canvas.querySelector('svg');
459	      if (!svg || !svgW) return;
460	
461	      constrainPan();
462	      svg.style.width = (svgW * zoom) + 'px';
463	      svg.style.height = (svgH * zoom) + 'px';
464	      canvas.style.transform = `translate(${panX}px, ${panY}px)`;
465	      label.textContent = Math.round(zoom * 100) + '% \u2014 ' + fitMode;
466	    }
467	
468	    function canPan() {
469	      const rW = svgW * zoom;
470	      const rH = svgH * zoom;
471	      return rW + config.fitPadding * 2 > viewport.clientWidth
472	          || rH + config.fitPadding * 2 > viewport.clientHeight;
473	    }
474	
475	    function computeSmartFit() {
476	      const vpW = viewport.clientWidth;
477	      const vpH = viewport.clientHeight;
478	      const aW = Math.max(80, vpW - config.fitPadding * 2);
479	      const aH = Math.max(80, vpH - config.fitPadding * 2);
480	      const contain = Math.min(aW / svgW, aH / svgH);
481	
482	      let z = contain;
483	      let mode = 'contain';
484	      if (contain < config.readabilityFloor) {
485	        const chartR = svgH / svgW;
486	        const vpR = vpH / Math.max(vpW, 1);
487	        if (chartR >= vpR) {
488	          z = aW / svgW;
489	          mode = 'width-priority';
490	        } else {
491	          z = aH / svgH;
492	          mode = 'height-priority';
493	        }
494	      }
495	      return { zoom: clamp(z, config.minZoom, config.maxInitialZoom), mode };
496	    }
497	
498	    function fitDiagram() {
499	      if (!svgW) return;
500	      const fit = computeSmartFit();
501	      zoom = fit.zoom;
502	      fitMode = fit.mode;
503	      panX = (viewport.clientWidth - svgW * zoom) / 2;
504	      panY = (viewport.clientHeight - svgH * zoom) / 2;
505	      applyTransform();
506	    }
507	
508	    function setOneToOne() {
509	      zoom = clamp(1, config.minZoom, config.maxZoom);
510	      fitMode = '1:1';
511	      panX = (viewport.clientWidth - svgW * zoom) / 2;
512	      panY = (viewport.clientHeight - svgH * zoom) / 2;
513	      applyTransform();
514	    }
515	
516	    function zoomAround(factor, cx, cy) {
517	      const next = clamp(zoom * factor, config.minZoom, config.maxZoom);
518	      const ratio = next / zoom;
519	      panX = cx - ratio * (cx - panX);
520	      panY = cy - ratio * (cy - panY);
521	      zoom = next;
522	      fitMode = 'custom';
523	      applyTransform();
524	    }
525	
526	    function readSvgNaturalSize(svg) {
527	      let w = 0;
528	      let h = 0;
529	      if (svg.viewBox?.baseVal?.width > 0) {
530	        w = svg.viewBox.baseVal.width;
531	        h = svg.viewBox.baseVal.height;
532	      }
533	      if (!w) {
534	        w = parseFloat(svg.getAttribute('width')) || 0;
535	        h = parseFloat(svg.getAttribute('height')) || 0;
536	      }
537	      if (!w) {
538	        const b = svg.getBBox();
539	        w = b.width;
540	        h = b.height;
541	      }
542	      if (!w) {
543	        const r = svg.getBoundingClientRect();
544	        w = r.width || 1000;
545	        h = r.height || 700;
546	      }
547	      if (!svg.getAttribute('viewBox')) {
548	        svg.setAttribute('viewBox', `0 0 ${w} ${h}`);
549	      }
550	      return { w, h };
551	    }
552	
553	    function setAdaptiveHeight() {
554	      if (!svgW) return;
555	      const usableW = Math.max(280, wrap.getBoundingClientRect().width - 2);
556	      const idealH = (svgH / svgW) * usableW + config.fitPadding * 2;
557	      const maxVp = Math.floor(innerHeight * config.maxHeightVh);
558	      const hardMax = Math.min(config.maxHeightPx, Math.max(config.minHeight + 40, maxVp));
559	      wrap.style.height = Math.round(clamp(idealH, config.minHeight, hardMax)) + 'px';
560	    }
561	
562	    function openInNewTab() {
563	      const svg = canvas.querySelector('svg');
564	      if (!svg) return;
565	
566	      const clone = svg.cloneNode(true);
567	      clone.style.width = '';
568	      clone.style.height = '';
569	
570	      // Use the same isDark value that was used to render the Mermaid theme
571	      // This ensures the background matches the baked-in SVG colors
572	      const bg = isDark ? '#042f2e' : '#f0fdfa';
573	
574	      const html = `<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8">
575	      <meta name="viewport" content="width=device-width, initial-scale=1.0">
576	      <title>Diagram</title><style>
577	      body{margin:0;min-height:100vh;display:flex;align-items:center;justify-content:center;
578	      background:${bg};padding:40px;box-sizing:border-box}
579	      svg{max-width:100%;max-height:90vh;height:auto}
580	      </style></head><body>${clone.outerHTML}</body></html>`;
581	
582	      open(URL.createObjectURL(new Blob([html], { type: 'text/html' })), '_blank');
583	    }
584	
585	    async function render() {
586	      try {
587	        const code = source.textContent.trim();
588	        if (!code) {
589	          label.textContent = 'Error: Empty source';
590	          return;
591	        }
592	
593	        const id = 'diagram-' + Date.now() + '-' + Math.random().toString(36).slice(2, 8);
594	        const { svg } = await mermaid.render(id, code);
595	        canvas.innerHTML = svg;
596	
597	        const svgNode = canvas.querySelector('svg');
598	        if (!svgNode) {
599	          label.textContent = 'Error: No SVG';
600	          return;
601	        }
602	
603	        const size = readSvgNaturalSize(svgNode);
604	        svgW = size.w;
605	        svgH = size.h;
606	
607	        svgNode.removeAttribute('width');
608	        svgNode.removeAttribute('height');
609	        svgNode.style.maxWidth = 'none';
610	        svgNode.style.display = 'block';
611	
612	        setAdaptiveHeight();
613	        fitDiagram();
614	      } catch (err) {
615	        console.error('Mermaid render failed:', err);
616	        label.textContent = 'Error: ' + (err.message || 'Render failed');
617	      }
618	    }
619	
620	    const actions = {
621	      'zoom-in': () => zoomAround(1 + config.zoomStep, viewport.clientWidth / 2, viewport.clientHeight / 2),
622	      'zoom-out': () => zoomAround(1 / (1 + config.zoomStep), viewport.clientWidth / 2, viewport.clientHeight / 2),
623	      'zoom-fit': fitDiagram,
624	      'zoom-one': setOneToOne,
625	      'zoom-expand': openInNewTab
626	    };
627	
628	    Object.entries(actions).forEach(([action, handler]) => {
629	      wrap.querySelector(`[data-action="${action}"]`)?.addEventListener('click', handler);
630	    });
631	
632	    viewport.addEventListener('dblclick', fitDiagram);
633	
634	    viewport.addEventListener('wheel', (e) => {
635	      if (e.ctrlKey || e.metaKey) {
636	        e.preventDefault();
637	        const rect = viewport.getBoundingClientRect();
638	        const factor = e.deltaY < 0 ? 1 + config.zoomStep : 1 / (1 + config.zoomStep);
639	        zoomAround(factor, e.clientX - rect.left, e.clientY - rect.top);
640	        return;
641	      }
642	      if (canPan()) {
643	        e.preventDefault();
644	        panX -= e.deltaX;
645	        panY -= e.deltaY;
646	        applyTransform();
647	      }
648	    }, { passive: false });
649	
650	    viewport.addEventListener('mousedown', (e) => {
651	      if (e.target.closest('.zoom-controls') || !canPan()) return;
652	      wrap.classList.add('is-panning');
653	      sx = e.clientX;
654	      sy = e.clientY;
655	      spx = panX;
656	      spy = panY;
657	      e.preventDefault();
658	
659	      activeDrag = {
660	        onMove: (ev) => {
661	          panX = spx + (ev.clientX - sx);
662	          panY = spy + (ev.clientY - sy);
663	          applyTransform();
664	        },
665	        onEnd: () => {
666	          wrap.classList.remove('is-panning');
667	        }
668	      };
669	    });
670	
671	    viewport.addEventListener('touchstart', (e) => {
672	      if (e.touches.length === 1) {
673	        sx = e.touches[0].clientX;
674	        sy = e.touches[0].clientY;
675	        spx = panX;
676	        spy = panY;
677	      } else if (e.touches.length === 2) {
678	        const dx = e.touches[0].clientX - e.touches[1].clientX;
679	        const dy = e.touches[0].clientY - e.touches[1].clientY;
680	        touchDist = Math.sqrt(dx * dx + dy * dy);
681	        const r = viewport.getBoundingClientRect();
682	        touchCx = (e.touches[0].clientX + e.touches[1].clientX) / 2 - r.left;
683	        touchCy = (e.touches[0].clientY + e.touches[1].clientY) / 2 - r.top;
684	      }
685	    }, { passive: true });
686	
687	    viewport.addEventListener('touchmove', (e) => {
688	      if (e.touches.length === 1 && canPan()) {
689	        if (touchDist > 0) {
690	          sx = e.touches[0].clientX;
691	          sy = e.touches[0].clientY;
692	          spx = panX;
693	          spy = panY;
694	          touchDist = 0;
695	        }
696	        e.preventDefault();
697	        panX = spx + (e.touches[0].clientX - sx);
698	        panY = spy + (e.touches[0].clientY - sy);
699	        applyTransform();
700	      } else if (e.touches.length === 2 && touchDist > 0) {
701	        e.preventDefault();
702	        const dx = e.touches[0].clientX - e.touches[1].clientX;
703	        const dy = e.touches[0].clientY - e.touches[1].clientY;
704	        const d = Math.sqrt(dx * dx + dy * dy);
705	        zoomAround(d / touchDist, touchCx, touchCy);
706	        touchDist = d;
707	      }
708	    }, { passive: false });
709	
710	    new ResizeObserver(() => {
711	      if (svgW) {
712	        setAdaptiveHeight();
713	        fitDiagram();
714	      }
715	    }).observe(wrap);
716	
717	    render();
718	  }
719	
720	  document.querySelectorAll('.diagram-shell').forEach(initDiagram);
721	</script>
