  { source: 'version_control', target: 'model_registry', throughput: 0.1, label: '0.1 Gbps', type: 'lineage' },
  { source: 'data_platform', target: 'version_control', throughput: 0.2, label: '0.2 Gbps', type: 'lineage' },
  { source: 'feature_store', target: 'inference_online', throughput: 6.0, label: '6.0 Gbps', type: 'primary' },
];

const layerColors = {
  'data': '#0891b2',
  'compute': '#059669',
  'serving': '#d97706',
  'observability': '#dc2626',
  'lineage': '#a78bfa',
};

const layerDimColors = {
  'data': 'rgba(8, 145, 178, 0.15)',
  'compute': 'rgba(5, 150, 105, 0.15)',
  'serving': 'rgba(217, 119, 6, 0.15)',
  'observability': 'rgba(220, 38, 38, 0.15)',
  'lineage': 'rgba(167, 139, 250, 0.15)',
};

function getNodeById(id) {
  return nodes.find(n => n.id === id);
}

function getNodeRadius(criticality) {
  return 28 + criticality * 2;
}

function drawNode(node) {
  const radius = getNodeRadius(node.criticality);
  const color = layerColors[node.layer];
  const dimColor = layerDimColors[node.layer];

  // Glow effect
  ctx.save();
  ctx.shadowColor = color;
  ctx.shadowBlur = 15;

  // Main circle
  ctx.beginPath();
  ctx.arc(node.x, node.y, radius, 0, Math.PI * 2);
  ctx.fillStyle = dimColor;
  ctx.fill();
  ctx.strokeStyle = color;
  ctx.lineWidth = 2;
  ctx.stroke();

  ctx.restore();

  // Label
  ctx.font = '600 13px "IBM Plex Sans", system-ui';
  ctx.fillStyle = '#e6edf3';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(node.label, node.x, node.y - 8);

  // Sublabel
  ctx.font = '400 10px "IBM Plex Mono", monospace';
  ctx.fillStyle = '#8b949e';
  ctx.fillText(node.sublabel, node.x, node.y + 8);

  // Criticality badge
  ctx.font = '500 9px "IBM Plex Mono", monospace';
  ctx.fillStyle = color;
  ctx.fillText(node.criticality, node.x + radius - 8, node.y - radius + 12);
}

function drawEdge(edge) {
  const source = getNodeById(edge.source);
  const target = getNodeById(edge.target);
  const maxThroughput = 12.5;
  const minWidth = 1;
  const maxWidth = 6;
  const strokeWidth = minWidth + (edge.throughput / maxThroughput) * (maxWidth - minWidth);

  let color;
  if (edge.type === 'lineage') {
    color = '#a78bfa';
  } else if (edge.type === 'feedback') {
    color = '#dc2626';
  } else {
    color = '#8b949e';
  }

  ctx.save();
  ctx.beginPath();
  ctx.moveTo(source.x, source.y);
  ctx.lineTo(target.x, target.y);
  ctx.strokeStyle = color;
  ctx.lineWidth = strokeWidth;

  if (edge.type === 'lineage') {
    ctx.setLineDash([6, 4]);
  } else if (edge.type === 'feedback') {
    ctx.setLineDash([4, 4]);
  }

  ctx.stroke();

  // Arrowhead
  const angle = Math.atan2(target.y - source.y, target.x - source.x);
  const arrowLength = 8;
  const arrowWidth = 4;

  ctx.setLineDash([]);
  ctx.beginPath();
  ctx.moveTo(target.x, target.y);
  ctx.lineTo(
    target.x - arrowLength * Math.cos(angle - Math.PI / 6),
    target.y - arrowLength * Math.sin(angle - Math.PI / 6)
  );
  ctx.lineTo(
    target.x - arrowLength * Math.cos(angle + Math.PI / 6),
    target.y - arrowLength * Math.sin(angle + Math.PI / 6)
  );
  ctx.closePath();
  ctx.fillStyle = color;
  ctx.fill();

  ctx.restore();

  // Edge label
  const midX = (source.x + target.x) / 2;
  const midY = (source.y + target.y) / 2;
  ctx.font = '400 9px "IBM Plex Mono", monospace';
  ctx.fillStyle = '#6b7280';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';

  // Background for label
  const labelText = edge.label;
  ctx.fillStyle = 'rgba(13, 17, 23, 0.8)';
  const labelWidth = ctx.measureText(labelText).width + 6;
  ctx.fillRect(midX - labelWidth / 2, midY - 7, labelWidth, 14);

  ctx.fillStyle = '#6b7280';
  ctx.fillText(labelText, midX, midY);
}

function render() {
  // Clear canvas
  ctx.fillStyle = '#0d1117';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // Draw edges first (behind nodes)
  edges.forEach(drawEdge);

  // Draw nodes
  nodes.forEach(drawNode);

  // Draw flow direction indicators for primary pipeline
  drawPipelineFlowIndicator();
}

function drawPipelineFlowIndicator() {
  // Highlight the primary pipeline path
  ctx.save();
  ctx.globalAlpha = 0.3;

  // Draw a subtle highlight on the main path
  ctx.restore();
}

// Auto-export to PNG on load
function exportPNG() {
  const dataURL = canvas.toDataURL('image/png');
  const link = document.createElement('a');
  link.download = 'result.png';
  link.href = dataURL;
  link.click();
}

// Export after a short delay to ensure rendering
setTimeout(exportPNG, 500);

render();
</script>

